mapper.select:
SELECT   gjl.*
  FROM   gld_je_line  gjl

         gjl.je_trx in ('PAY_EQIPMENT' , 'CSH_DEDUCTION')
         and gjl.account_id = #{accountId}
         and gjl.dr_cr = #{drCr}
         and gjl.je_head_id = #{jeHeadId}

select gjl.je_head_id, gjl.je_description, gjl.segment_1, gjl.segment_2, gjl.segment_3, gjl.segment_4, gjl.segment_5, nvl(gjl.dr_amount, 0) dr_total, nvl(gjl.cr_amount, 0) cr_total, nvl(gjl.dr_functional_amount, 0) dr_functional_amount_total, nvl(gjl.cr_functional_amount, 0) cr_functional_amount_total from gld_je_line gjl
and gjl.je_line_id in
#{item}
and gjl.je_line_id = -1
and gjl.je_line_id = #{jeLineId}

select (select gc.account_code from gld_account gc where gc.account_id = gjl.account_id)account_code, (select ga.account_name from gld_account ga where ga.account_id = gjl.account_id) account_id_n, gjl.je_head_id, gjl.je_description, gjl.segment_1, gjl.segment_2, gjl.segment_3, gjl.segment_4, gjl.segment_5, nvl(gjl.dr_amount, 0) dr_amount, nvl(gjl.cr_amount, 0) cr_amount, nvl(gjl.dr_functional_amount, 0) dr_functional_amount, nvl(gjl.cr_functional_amount, 0) cr_functional_amount from gld_je_line gjl
and gjl.je_head_id = #{jeHeadId}
order by gjl.cr_amount desc,gjl.dr_amount desc
